ASSETS={'/locales/messages.js':'messages.js','/tf/quality-ui.js':'quality-ui.js','/tf/m1-basemap-data.js':'m1-basemap-data.js','/tf/m1-map.js':'m1-map.js','/tf/map-gestures.js':'map-gestures.js','/admin/quality.js':'admin-quality.js','/admin/report-review.js':'report-review.js'}
def fixture():
 html=localize_html((STATIC/'admin-quality.html').read_text());html=re.sub(r'<script.*?</script>','',html,flags=re.S);html=html.replace('</main>','<dialog id="reportDialog" data-report-id="2"><div id="reportDetailBody"></div><p id="reportDetailMessage"></p></dialog></main>')
 setup=r'''window.I18n={t:s=>s,locale:'de-DE'};let decision=null,backupRequested=false,enabled=true,reviewState='received',reviewRevision=0;const token='a'.repeat(64),point={latitude:51.1,longitude:13.1,source_name:'TF-GPS'};const current={coordinate:point,token};let reviewed=false;window.fetch=async(path,o={})=>{let data;const url=String(path);if(url.endsWith('/admin/me'))data={id:1,role:'admin',permissions:{employees:3,knowledge:3,work_reports:3}};else if(url.includes('/coordinates?'))data={items:reviewed?[]:[{id:1,code:'QA',name:'Prüfort',owner_id:11,at:'2026-11-23T10:00:00',before:{...point,latitude:51.11},after:point,current,history:[]}],total:reviewed?0:1,can_write:true};else if(url.endsWith('/coordinates/1')){decision=JSON.parse(o.body);reviewed=true;data={state:'verified'};}else if(url.endsWith('/backups/request')){backupRequested=true;data={state:'queued'};}else if(url.endsWith('/backups')){if(o.method==='PUT')enabled=JSON.parse(o.body).enabled;data={enabled,requested:backupRequested,items:[{id:'x',state:'verified',created_at:'2026-11-23T10:00:00',summary:{tables:90,rows:123,files:4,verification:'isolated-sqlite-and-files'}}]};}else if(url.endsWith('/review')){const p=JSON.parse(o.body);if(p.expected_revision!==reviewRevision||p.expected_sha256!==token)return new Response(JSON.stringify({detail:'Stand geändert'}),{status:409});reviewState=p.state;reviewRevision++;data={state:reviewState};}else data={items:[]};return new Response(JSON.stringify(data));};'''
 checks=r'''
(async()=>{const assert=(v,m)=>{if(!v)throw Error(m);},wait=()=>new Promise(r=>setTimeout(r,25)),until=async fn=>{const end=performance.now()+15000;while(!fn()){if(performance.now()>end)throw Error('Timeout '+document.body.textContent);await wait();}};await until(()=>document.querySelector('#qualityContent tbody button'));document.querySelector('#qualityContent tbody button').click();await until(()=>document.querySelector('dialog[open] [data-coordinate-position=before]'));assert(document.querySelector('dialog[open] [data-coordinate-position=after]'),'Before and proposed coordinates visible on real offline background');const dialog=document.querySelector('dialog[open]'),buttons=[...dialog.querySelectorAll('button')],confirm=buttons.find(b=>b.textContent===RailQuality.t('confirm'));confirm.click();await wait();assert(!decision,'A review needs a comment');dialog.querySelector('textarea').value='Position geprüft';confirm.click();await until(()=>decision);assert(decision.expected_token===token&&decision.comment==='Position geprüft','Decision bound to displayed coordinates');await until(()=>!dialog.open);
 const backups=[...document.querySelectorAll('#qualityTabs button')].find(b=>b.textContent===RailQuality.t('backups'));backups.click();await until(()=>document.querySelector('#qualityContent input[type=checkbox]'));assert(document.querySelector('#qualityContent table').textContent.includes('123'),'Verified backup result visible');const toggle=document.querySelector('#qualityContent input');toggle.checked=false;toggle.dispatchEvent(new Event('change'));await until(()=>!enabled);[...document.querySelectorAll('#qualityContent button')].find(b=>b.textContent===RailQuality.t('backup_now')).click();await until(()=>backupRequested);await until(()=>document.getElementById('qualityMessage').textContent.includes(RailQuality.t('backup_pending')));assert(document.getElementById('qualityMessage').textContent.includes(RailQuality.t('backup_pending')),'Request is queued for worker, not claimed as completed');
 const reportDialog=document.getElementById('reportDialog');reportDialog.showModal();function show(){window.dispatchEvent(new CustomEvent('report-review-open',{detail:{id:2,data:{can_review:true,report:{review:{state:reviewState,revision:reviewRevision,version:1,payload_sha256:token,history:[{at:'2026-11-23T10:00',version:1,state:'received',comment:'Import'}]}}}}}));}window.addEventListener('report-review-refresh',show);show();assert(![...document.querySelectorAll('#reportReviewPanel button')].some(b=>b.textContent===RailQuality.t('approved')),'No immediate approval without review');[...document.querySelectorAll('#reportReviewPanel button')].find(b=>b.textContent===RailQuality.t('in_review')).click();await until(()=>reviewState==='in_review');await until(()=>[...document.querySelectorAll('#reportReviewPanel button')].some(b=>b.textContent===RailQuality.t('approved')));document.querySelector('#reportReviewPanel textarea').value='Vollständig geprüft';[...document.querySelectorAll('#reportReviewPanel button')].find(b=>b.textContent===RailQuality.t('approved')).click();await until(()=>reviewState==='approved');assert(reviewRevision===2,'One version-bound transition for each action');parent.postMessage({layoutStatus:'pass'},'*');})().catch(e=>parent.postMessage({layoutStatus:'fail',message:e.stack},'*'));
'''
 return html.replace('</body>','<script>'+setup+'</script>'+''.join('<script src="'+path+'"></script>' for path in ASSETS)+'<script>'+checks+'</script></body>')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output-dir',required=True);a=p.parse_args();check_pages(fixture,a.output_dir,widths=(800,375),assets={path:STATIC/name for path,name in ASSETS.items()},label='Administrative quality and review',timeout=40)
